insert into public.drugs (name, generic_name, category, uses, dosage, side_effects, pregnancy_safe, alcohol_safe, lactation_safe, prescription_required) values
  ('Amoxicillin', 'Amoxicillin', 'Antibiotic', 'Treats bacterial infections including pneumonia, ear infections, UTIs, and skin infections.', 'Adults: 250-500mg every 8 hours. Children: 25mg/kg/day in divided doses.', 'Nausea, diarrhea, rash, allergic reactions.', true, false, true, 'Yes'),
  ('Paracetamol', 'Acetaminophen', 'Analgesic / Antipyretic', 'Relieves mild to moderate pain and reduces fever.', 'Adults: 500-1000mg every 4-6 hours. Max 4g/day. Children: 10-15mg/kg every 4-6 hours.', 'Rarely causes side effects at normal doses. Overdose can cause liver damage.', true, false, true, 'No'),
  ('Metformin', 'Metformin Hydrochloride', 'Antidiabetic', 'Controls blood sugar levels in type 2 diabetes.', 'Adults: 500mg twice daily with meals. Max 2000mg/day.', 'Nausea, vomiting, diarrhea, stomach upset.', false, false, false, 'Yes'),
  ('Ibuprofen', 'Ibuprofen', 'NSAID / Anti-inflammatory', 'Reduces pain, fever and inflammation. Used for headaches, arthritis, menstrual cramps.', 'Adults: 200-400mg every 4-6 hours. Max 1200mg/day without prescription.', 'Stomach upset, heartburn, nausea, increased bleeding risk.', false, false, false, 'No'),
  ('Ciprofloxacin', 'Ciprofloxacin', 'Antibiotic', 'Treats urinary tract infections, respiratory infections, typhoid fever.', 'Adults: 250-750mg twice daily for 7-14 days.', 'Nausea, diarrhea, dizziness, tendon damage with prolonged use.', false, false, false, 'Yes'),
  ('Artemether/Lumefantrine', 'Artemether + Lumefantrine', 'Antimalarial', 'First-line treatment for uncomplicated malaria in Kenya.', 'Adults: 4 tablets at 0, 8, 24, 36, 48, 60 hours (6 doses total).', 'Headache, dizziness, nausea, vomiting, loss of appetite.', false, false, true, 'Yes'),
  ('Omeprazole', 'Omeprazole', 'Proton Pump Inhibitor', 'Treats acid reflux, stomach ulcers, and heartburn.', 'Adults: 20-40mg once daily before meals.', 'Headache, nausea, diarrhea, stomach pain.', false, false, false, 'No'),
  ('Amlodipine', 'Amlodipine Besylate', 'Calcium Channel Blocker', 'Treats high blood pressure and chest pain (angina).', 'Adults: 5-10mg once daily.', 'Swelling of ankles, flushing, headache, dizziness.', false, false, false, 'Yes');
